  function renderProductFilters(snapshot){const root=document.querySelector('[data-seller-product-filters]');if(!root)return;const products=Array.isArray(snapshot.products)?snapshot.products:[];const counts={all:products.length,active:0,paused:0,draft:0,out:0};products.forEach(product=>{const state=effectiveProductStatus(product);if(Object.prototype.hasOwnProperty.call(counts,state))counts[state]+=1;});root.innerHTML=[filterButton('product','all','Все',counts.all,productFilter==='all'),filterButton('product','active','На витрине',counts.active,productFilter==='active'),filterButton('product','paused','Скрытые',counts.paused,productFilter==='paused'),filterButton('product','out','Нет в наличии',counts.out,productFilter==='out'),filterButton('product','draft','Черновики',counts.draft,productFilter==='draft')].join('');}
  function stockActions(product){const qty=Number(product.stock_qty||0);if(qty>3)return `<button class="k-btn k-btn-ghost k-btn-sm" type="button" data-seller-stock-open="${esc(product.id)}">Остаток ${qty}</button>`;return `<div class="k-seller-stock-quick"><button type="button" data-seller-stock-delta="${esc(product.id)}" data-delta="1">+1</button><button type="button" data-seller-stock-delta="${esc(product.id)}" data-delta="5">+5</button><button type="button" data-seller-stock-open="${esc(product.id)}">Остаток ${qty}</button></div>`;}
  function productCard(product,categories){const category=categories.get(String(product.category||'')),paused=product.status==='paused',draft=product.status==='draft',state=effectiveProductStatus(product);return `<div class="k-seller-r83-row k-seller-r83-product-row" data-seller-product-id="${esc(product.id)}"><div class="k-seller-r83-row-main"><span class="k-seller-r83-thumb">${product.image_url?`<img src="${esc(product.image_url)}" alt="">`:categorySvg(category||{key:product.category,name:product.category})}</span><span><b>${esc(product.name)}</b><small>${esc(category?.name||product.category||'Другое')} · ${esc(product.sku)}${product.oem_number?' · OEM '+esc(product.oem_number):''}</small></span></div><span class="k-seller-r83-state is-${esc(state)}">${esc(productStatusLabel(state))}</span><strong>${money(product.price)}</strong><em class="${Number(product.stock_qty)<=3?'is-low':''}">Остаток ${esc(product.stock_qty)}</em><div class="k-seller-r83-actions"><a class="k-btn k-btn-ghost k-btn-sm" href="#/parts/item/${encodeURIComponent(String(product.id||''))}">Открыть</a><button class="k-btn k-btn-ghost k-btn-sm" type="button" data-seller-edit="${esc(product.id)}">Редактировать</button>${stockActions(product)}${paused||draft?`<button class="k-btn k-btn-primary k-btn-sm" type="button" data-seller-visibility="${esc(product.id)}" data-status="active">Опубликовать</button>`:`<button class="k-btn k-btn-ghost k-btn-sm" type="button" data-seller-visibility="${esc(product.id)}" data-status="paused">Скрыть</button>`}<button class="k-btn k-btn-ghost k-btn-sm is-danger" type="button" data-seller-archive="${esc(product.id)}">В архив</button></div></div>`;}
  function renderProductList(snapshot){const root=document.querySelector('[data-seller-products]');if(!root)return;renderProductFilters(snapshot);const categories=categoryMap(snapshot.categories),query=productSearch.trim().toLowerCase();const rows=(snapshot.products||[]).filter(product=>(productFilter==='all'||effectiveProductStatus(product)===productFilter)&&(!query||[product.name,product.sku,product.oem_number,product.brand].some(value=>String(value||'').toLowerCase().includes(query))));root.innerHTML=rows.length?rows.map(product=>productCard(product,categories)).join(''):`<div class="k-empty">${query||productFilter!=='all'?'По выбранному фильтру товаров нет.':'Товаров пока нет. Добавьте первую запчасть в каталог.'}</div>`;}
  function renderArchive(snapshot){const root=document.querySelector('[data-seller-archive-products]'),count=document.querySelector('[data-seller-archive-count]');if(!root)return;const rows=Array.isArray(snapshot.archivedProducts)?snapshot.archivedProducts:[];if(count)count.textContent=String(rows.length);const categories=categoryMap(snapshot.categories);root.innerHTML=rows.length?rows.map(product=>{const category=categories.get(String(product.category||''));return `<div class="k-seller-r83-row k-seller-r83-archive-row"><div class="k-seller-r83-row-main"><span class="k-seller-r83-thumb">${categorySvg(category||{key:product.category,name:product.category})}</span><span><b>${esc(product.name)}</b><small>${esc(product.sku)} · ${money(product.price)} · остаток ${Number(product.stock_qty||0)}</small></span></div><button class="k-btn k-btn-secondary k-btn-sm" type="button" data-seller-restore="${esc(product.id)}">Восстановить</button></div>`;}).join(''):'<div class="k-empty">Архив пуст.</div>';}
  function orderActionButtons(order){const status=String(order.status||'new'),pickup=String(order.delivery_type||'pickup')==='pickup',buttons=[];if(status==='new')buttons.push(['confirmed','Подтвердить','primary']);if(status==='confirmed')buttons.push(['packed','Собран','primary']);if(status==='packed')buttons.push([pickup?'delivered':'shipped',pickup?'Выдать покупателю':'Передать в доставку','primary']);if(status==='shipped')buttons.push(['delivered','Подтвердить выдачу','primary']);if(['new','confirmed','packed'].includes(status))buttons.push(['cancelled','Отменить','danger']);if(status==='delivered')buttons.push(['returned','Оформить возврат','ghost']);return buttons.map(([next,label,tone])=>`<button type="button" class="k-btn k-btn-sm ${tone==='primary'?'k-btn-primary':'k-btn-ghost'}${tone==='danger'?' is-danger':''}" data-seller-order-action="${esc(order.id)}" data-status="${esc(next)}">${esc(label)}</button>`).join('');}
