  function orderCard(order){const status=String(order.status||'new');return `<div class="k-seller-r83-row k-seller-r83-order-row is-${esc(status)}"><div class="k-seller-r83-row-main"><span><b>Заказ ${esc(String(order.id||'').replace(/^sord_/,'#').slice(0,14))}</b><small>${esc(order.customer_name||'Покупатель')} · ${esc(dateTime(order.created_at))}</small></span></div><span class="k-seller-r83-state">${esc(orderStatusLabel(status))}</span><span>${esc(deliveryLabel(order.delivery_type))}</span><strong>${money(order.total)}</strong><div class="k-seller-r83-actions"><button type="button" class="k-btn k-btn-ghost k-btn-sm" data-seller-order-open="${esc(order.id)}">Открыть</button>${chatButton(order)}${orderActionButtons(order)}</div></div>`;}
  function orderDetailContent(order){const items=Array.isArray(order.items)?order.items:[],status=String(order.status||'new');return `<article class="k-seller-order-detail is-${esc(status)}"><div class="k-seller-order-customer"><div><span>Покупатель</span><b>${esc(order.customer_name||'Покупатель')}</b><small>${esc(maskPhone(order.customer_phone))}</small></div><div><span>Получение</span><b>${esc(deliveryLabel(order.delivery_type))}</b><small>${esc(order.delivery_address||'Адрес не требуется')}</small></div></div><div class="k-seller-order-items">${items.length?items.map(item=>`<div><span><b>${esc(item.name)}</b><small>${esc(item.sku||'')}</small></span><em>${esc(item.qty)} × ${money(item.price)}</em><strong>${money(item.total)}</strong></div>`).join(''):'<div class="k-seller-order-item-empty">Состав заказа недоступен</div>'}</div><div class="k-seller-order-summary"><div><span>Товары</span><strong>${money(order.subtotal||order.total)}</strong></div><div><span>Доставка</span><strong>${money(order.delivery_price||0)}</strong></div><div><span>Итого</span><strong>${money(order.total)}</strong></div></div>${order.comment?`<div class="k-seller-order-comment"><span>Комментарий</span><p>${esc(order.comment)}</p></div>`:''}<footer><div class="k-seller-order-payment"><span>${esc(paymentLabel(order.payment_status))}</span>${terminalOrder(status)?'<small>Заказ завершён</small>':'<small>Следующий шаг выбирается кнопкой</small>'}${Number(order.client_user_id||0)<=0?'<small>Покупатель оформил заказ без доступного аккаунта чата.</small>':''}</div><div class="k-seller-order-actions">${chatButton(order,'Написать покупателю')}${orderActionButtons(order)}</div></footer></article>`;}
  function openOrderDialog(id){const order=(store.getSnapshot().orders||[]).find(row=>String(row.id)===String(id)),dialog=document.querySelector('[data-seller-order-dialog]'),root=dialog?.querySelector('[data-seller-order-detail]');if(!order||!dialog||!root)return;dialog.querySelector('[data-seller-order-dialog-title]').textContent=`${orderStatusLabel(order.status)} · ${money(order.total)}`;root.innerHTML=orderDetailContent(order);dialog.showModal();}
  function renderOrderFilters(snapshot){const root=document.querySelector('[data-seller-order-filters]');if(!root)return;const orders=Array.isArray(snapshot.orders)?snapshot.orders:[],active=orders.filter(o=>!terminalOrder(o.status)).length,done=orders.filter(o=>o.status==='delivered').length,issue=orders.filter(o=>['returned','cancelled'].includes(o.status)).length;root.innerHTML=[filterButton('order','active','В работе',active,orderFilter==='active'),filterButton('order','all','Все',orders.length,orderFilter==='all'),filterButton('order','done','Выданы',done,orderFilter==='done'),filterButton('order','issue','Возвраты / отмены',issue,orderFilter==='issue')].join('');}
  function renderOrderList(snapshot){const root=document.querySelector('[data-seller-orders]');if(!root)return;renderOrderFilters(snapshot);const query=orderSearch.trim().toLowerCase();const orders=(snapshot.orders||[]).filter(order=>(orderFilter==='all'||(orderFilter==='active'&&!terminalOrder(order.status))||(orderFilter==='done'&&order.status==='delivered')||(orderFilter==='issue'&&['returned','cancelled'].includes(order.status)))&&(!query||[order.id,order.customer_name,order.customer_phone].some(value=>String(value||'').toLowerCase().includes(query))));root.innerHTML=orders.length?orders.map(orderCard).join(''):`<div class="k-empty">${query?'Заказы по запросу не найдены.':'Заказов в этом разделе пока нет.'}</div>`;}
  function renderAttention(snapshot){const root=document.querySelector('[data-seller-attention]');if(!root)return;const products=Array.isArray(snapshot.products)?snapshot.products:[],orders=Array.isArray(snapshot.orders)?snapshot.orders:[];const out=products.filter(p=>Number(p.stock_qty||0)<=0).length,low=products.filter(p=>Number(p.stock_qty||0)>0&&Number(p.stock_qty||0)<=3).length,newOrders=orders.filter(o=>o.status==='new').length,issues=orders.filter(o=>['returned','cancelled'].includes(o.status)).length,archive=(snapshot.archivedProducts||[]).length;const cards=[];if(newOrders)cards.push(`<a href="#/seller/orders"><b>${newOrders}</b><span>новых заказов</span><small>Нужно подтвердить</small></a>`);if(out)cards.push(`<a href="#/seller/products"><b>${out}</b><span>без остатка</span><small>Пополните прямо из карточки</small></a>`);if(low)cards.push(`<a href="#/seller/products"><b>${low}</b><span>заканчиваются</span><small>Остаток 1–3 шт.</small></a>`);if(issues)cards.push(`<a href="#/seller/orders"><b>${issues}</b><span>возвратов / отмен</span><small>Проверьте журнал</small></a>`);if(archive)cards.push(`<a href="#/seller/products"><b>${archive}</b><span>в архиве</span><small>Можно восстановить в черновики</small></a>`);root.innerHTML=cards.length?`<div class="k-seller-attention-head"><h2>Требует внимания</h2><span>${cards.length}</span></div><div class="k-seller-attention-grid">${cards.join('')}</div>`:`<div class="k-seller-attention-clear"><b>Рабочая очередь чистая</b><span>Новых проблем по товарам и заказам нет.</span></div>`;}
  function renderOperations(snapshot){const root=document.querySelector('[data-seller-operations]');if(!root)return;const rows=[];const orders=Array.isArray(snapshot.orders)?snapshot.orders:[];const products=Array.isArray(snapshot.products)?snapshot.products:[];orders.filter(order=>order.status==='new').slice(0,8).forEach(order=>rows.push(`<div class="k-seller-r83-operation is-order"><span><b>Новый заказ ${esc(String(order.id||'').replace(/^sord_/,'#').slice(0,14))}</b><small>${esc(order.customer_name||'Покупатель')} · ${money(order.total)}</small></span><button class="k-btn k-btn-primary k-btn-sm" type="button" data-seller-order-open="${esc(order.id)}">Открыть</button></div>`));products.filter(product=>Number(product.stock_qty||0)<=0).slice(0,8).forEach(product=>rows.push(`<div class="k-seller-r83-operation is-stock"><span><b>Нет в наличии: ${esc(product.name)}</b><small>${esc(product.sku||'')} · товар скрывается из доступного остатка</small></span><button class="k-btn k-btn-ghost k-btn-sm" type="button" data-seller-stock-open="${esc(product.id)}">Остаток</button></div>`));products.filter(product=>Number(product.stock_qty||0)>0&&Number(product.stock_qty||0)<=3).slice(0,8).forEach(product=>rows.push(`<div class="k-seller-r83-operation is-stock"><span><b>Заканчивается: ${esc(product.name)}</b><small>Остаток ${Number(product.stock_qty||0)} шт.</small></span><button class="k-btn k-btn-ghost k-btn-sm" type="button" data-seller-stock-open="${esc(product.id)}">Пополнить</button></div>`));const archived=Array.isArray(snapshot.archivedProducts)?snapshot.archivedProducts:[];if(archived.length)rows.push(`<div class="k-seller-r83-operation is-archive"><span><b>В архиве ${archived.length}</b><small>Восстановление доступно в разделе Товары.</small></span><a class="k-btn k-btn-ghost k-btn-sm" href="#/seller/products">Открыть</a></div>`);const p=snapshot.profile||{};if(String(p.moderation_status||'pending')!=='approved')rows.unshift(`<div class="k-seller-r83-operation is-profile"><span><b>${esc(moderationMeta(p.moderation_status,p.moderation_reason)[0])}</b><small>${esc(moderationMeta(p.moderation_status,p.moderation_reason)[1])}</small></span><button class="k-btn k-btn-ghost k-btn-sm" type="button" data-seller-open-profile>Профиль</button></div>`);root.innerHTML=rows.length?rows.join(''):'<div class="k-seller-r83-empty"><b>Рабочая очередь чистая</b><span>Новых заказов и проблем по остаткам нет.</span></div>';root.querySelectorAll('[data-seller-open-profile]').forEach(button=>button.addEventListener('click',openProfileDialog));}
  function renderSnapshot(snapshot){const status=document.querySelector('[data-seller-status]'),stats=document.querySelector('[data-seller-stats]');if(!status||!stats)return;if(snapshot.status==='loading'){status.textContent='Загружаем магазин, товары и заказы…';status.className='k-seller-status is-loading';return;}if(snapshot.status==='error'){status.textContent=snapshot.error?.message||'Не удалось загрузить кабинет продавца.';status.className='k-seller-status is-error';return;}const meta=moderationMeta(snapshot.profile?.moderation_status,snapshot.profile?.moderation_reason);status.textContent=meta[0];status.className=`k-seller-status is-${meta[2]}`;const metrics=snapshot.metrics||{};stats.innerHTML=[metric('Товаров',metrics.products||0,'📦'),metric('В наличии',metrics.in_stock||0,'✓'),metric('Новых заказов',metrics.new_orders||0,'🧾'),metric('Выручка',money(metrics.revenue||0),'₸')].join('');const categoryRoot=document.querySelector('[data-seller-category-choices]');if(categoryRoot&&!document.querySelector('[data-seller-dialog]')?.open)categoryRoot.innerHTML=categoryChoices(snapshot.categories);renderProfileSummary(snapshot);renderAttention(snapshot);renderOperations(snapshot);renderProductList(snapshot);renderArchive(snapshot);renderOrderList(snapshot);}
  function setChoice(form,name,value){const input=Array.from(form?.querySelectorAll(`input[name="${name}"]`)||[]).find(row=>String(row.value)===String(value||''));if(input)input.checked=true;}
